/* cu-effects:line — flagship hairline product language: warm canvas, paper rail, no scaffold grid. */
:root {
  --cu-tracking: -0.011em;
  --cu-font-weight-heading: 600;
  -webkit-font-smoothing: antialiased;
}

:root .cu-app-shell {
  background-color: var(--cu-color-background-subtle);
  letter-spacing: var(--cu-tracking);
}

:root .cu-app-shell__header {
  background: var(--cu-color-background-elevated);
  box-shadow: none;
  border-block-end: var(--cu-border-width-hairline, 1px) solid var(--cu-color-border-default);
}

:root .cu-app-shell__main {
  background-color: var(--cu-color-background-subtle);
  background-image: none;
}

:root .cu-app-shell__sidebar,
:root .cu-sidebar,
:root .cu-navigation__frame {
  background: var(--cu-color-background-elevated);
  border-inline-end: var(--cu-border-width-hairline, 1px) solid var(--cu-color-border-default);
}

:root .cu-sidebar__item[aria-current='page'],
:root .cu-navigation__item[aria-current='page'] {
  border-inline-start: none;
  border-radius: var(--cu-radius-sm);
  background: color-mix(in srgb, var(--cu-color-fg-default) 6%, transparent);
  color: var(--cu-color-fg-default);
  font-weight: var(--cu-typography-weight-semibold, 600);
}

:root .cu-heading,
:root .cu-typography--heading-1,
:root .cu-typography--heading-2,
:root .cu-navigation-bar__title,
:root .cu-navigation__header {
  font-weight: var(--cu-font-weight-heading, 600);
  letter-spacing: var(--cu-typography-tracking-tight, -0.022em);
}

:root .cu-button {
  font-weight: var(--cu-typography-weight-medium, 500);
  letter-spacing: -0.014em;
}

:root .cu-card,
:root .cu-card--default,
:root .cu-card--elevated {
  box-shadow: var(--cu-shadow-sm);
  border: var(--cu-border-width-hairline, 1px) solid var(--cu-color-border-default);
  background: var(--cu-color-background-elevated);
}

:root .cu-empty-state__description,
:root .cu-typography--caption,
:root .cu-field__label {
  color: var(--cu-color-fg-muted);
}

:root .cu-dialog__backdrop {
  background: color-mix(in srgb, var(--cu-color-background-inverse) 40%, transparent);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}

:root .cu-dialog__content,
:root .cu-tab-bar,
:root .cu-navigation {
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  background: var(--cu-color-background-elevated);
}

:root .cu-input:focus-visible,
:root .cu-button:focus-visible {
  outline: 2px solid var(--cu-color-fg-default);
  outline-offset: 2px;
}

{
  "radius": {
    "sm": { "$value": { "value": 4, "unit": "px" } },
    "md": { "$value": { "value": 8, "unit": "px" } },
    "lg": { "$value": { "value": 12, "unit": "px" } },
    "xl": { "$value": { "value": 16, "unit": "px" } }
  },
  "shadow": {
    "sm": {
      "$value": "0 1px 2px color-mix(in srgb, {color.palette.ink} 5%, transparent)"
    },
    "md": {
      "$value": "0 4px 12px color-mix(in srgb, {color.palette.ink} 8%, transparent)"
    },
    "lg": {
      "$value": "0 12px 32px color-mix(in srgb, {color.palette.ink} 12%, transparent)"
    }
  },
  "motion": {
    "duration": {
      "fast": { "$value": "120ms" },
      "base": { "$value": "180ms" },
      "slow": { "$value": "240ms" }
    },
    "easing": {
      "standard": { "$value": "cubic-bezier(0.25, 0.1, 0.25, 1)" },
      "enter": { "$value": "cubic-bezier(0, 0, 0.2, 1)" },
      "exit": { "$value": "cubic-bezier(0.4, 0, 1, 1)" }
    }
  },
  "blur": {
    "surface": { "$value": { "value": 0, "unit": "px" } },
    "overlay": { "$value": { "value": 0, "unit": "px" } },
    "thick": { "$value": { "value": 0, "unit": "px" } }
  },
  "border-width": {
    "$type": "dimension",
    "hairline": { "$value": { "value": 1, "unit": "px" } },
    "default": { "$value": { "value": 1, "unit": "px" } }
  },
  "color": {
    "palette": {
      "brand": { "$value": "#171717" },
      "ink": { "$value": "#111110" },
      "paper": { "$value": "#fbfbfa" }
    },
    "background": {
      "default": { "$value": "{color.palette.paper}" },
      "subtle": { "$value": "#f4f3ef" },
      "elevated": { "$value": "#ffffff" },
      "inverse": { "$value": "{color.palette.ink}" }
    },
    "border": {
      "default": { "$value": "#e7e5e0" }
    },
    "fg": {
      "default": { "$value": "{color.palette.ink}" },
      "muted": { "$value": "#73716c" },
      "inverse": { "$value": "#fafafa" }
    }
  },
  "typography": {
    "line-height": {
      "body": { "$value": 1.5 }
    },
    "tracking": {
      "tight": { "$value": "-0.022em" },
      "body": { "$value": "-0.011em" }
    }
  }
}
